mapper.select:
SELECT COUNT(*) 
FROM shop
WHERE shop_name=#{shopName}

mapper.update:
        UPDATE shop SET
        	shop_name 	= #{shopName}
			,telephone	= #{telephone}
			,shop_stat_ty_cd	= #{shopStatTyCd}
			,lat		= #{lat}
			,lot		= #{lot}
        WHERE
        	shop_id 			= #{shopId}

mapper.select:
SELECT COUNT(*)
FROM
	shop_new_cstmr
WHERE
	shop_id=#{shopId}
	and join_date=#{joinDate}

mapper.update:
UPDATE shop_new_cstmr SET
	join_count=#{joinCount}
WHERE
	shop_id 			= #{shopId}
	AND join_date		= #{joinDate}
